function hashStr(str) { let h = 2166136261; for (const c of str) h = Math.imul(h ^ c.charCodeAt(0), 16777619); return h >>> 0; }

const DAY_NAMES = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'];

// The calendar: by default Day 1 is a Monday. A fresh browser world aligns
// Day 100 with the player's real date (offset = weekday shift, epoch = ms of Day 1).
const CAL = { offset: 0, epoch: null };
function setCalendar(c) { CAL.offset = c?.offset ?? 0; CAL.epoch = c?.epoch ?? null; }
function dowOf(day) { return ((day + CAL.offset) % 7 + 7) % 7; }
const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
function dateOf(day) { if (CAL.epoch == null) return null; const d = new Date(CAL.epoch + day * 86400000); return `${MONTHS[d.getMonth()]} ${d.getDate()}`; }
function clockLabel(t) {
  const day = Math.floor(t / 1440);
  const m = t % 1440;
  const hh = String(Math.floor(m / 60)).padStart(2, '0');
  const mm = String(m % 60).padStart(2, '0');
  const date = dateOf(day);
  return `${DAY_NAMES[dowOf(day)]}${date ? `, ${date}` : ''} (Day ${day + 1}) ${hh}:${mm}`;
}
function isWeekend(t) { const day = Math.floor(t / 1440); return dowOf(day) >= 5 || !!holidayOf(day)?.closed; }

// ---- Seasons, weather and holidays (northern hemisphere, from the real date when known).
function calDate(day) { return new Date((CAL.epoch ?? Date.UTC(2026, 6, 1)) + day * 86400000); } // headless: Day 1 = July 1
function seasonOf(day) { const m = calDate(day).getMonth(); return m < 2 || m === 11 ? 'winter' : m < 5 ? 'spring' : m < 8 ? 'summer' : 'autumn'; }
const WEATHER_ODDS = {
  winter: [['cloudy', 3], ['snow', 2], ['sunny', 2], ['rain', 2], ['fog', 1]],
  spring: [['sunny', 4], ['rain', 3], ['cloudy', 2], ['storm', 1]],
  summer: [['sunny', 6], ['heat', 2], ['storm', 1], ['cloudy', 1]],
  autumn: [['cloudy', 3], ['rain', 3], ['sunny', 3], ['fog', 1], ['storm', 1]],
};
const TEMPS = { winter: 2, spring: 14, summer: 26, autumn: 13 };
function weatherOf(day) {
  const season = seasonOf(day), odds = WEATHER_ODDS[season];
  let h = (day * 2654435761 >>> 0) % 1000 / 1000 * odds.reduce((s, x) => s + x[1], 0), kind = odds[0][0];
  for (const [k, w] of odds) { h -= w; if (h <= 0) { kind = k; break; } }
  const temp = TEMPS[season] + (kind === 'heat' ? 9 : kind === 'snow' ? -4 : kind === 'sunny' ? 3 : 0) + ((day * 7919) % 7) - 3;
  return { kind, season, temp, icon: { sunny: '☀️', cloudy: '☁️', rain: '🌧️', storm: '⛈️', snow: '❄️', fog: '🌫️', heat: '🥵' }[kind] };
}
function holidayOf(day) {
  if (CAL.epoch == null) return null;
  const d = calDate(day), m = d.getMonth() + 1, dd = d.getDate(), dw = d.getDay(); // dw: 0 = Sunday
  if (m === 10 && dd === 31) return { id: 'halloween', name: 'Halloween costume party', start: 16 * 60, emoji: '🎃' };
  if (m === 11 && dw === 4 && dd >= 22 && dd <= 28) return { id: 'friendsgiving', name: 'Friendsgiving potluck', start: 12 * 60 + 30, emoji: '🦃' };
  if (m === 12 && dw === 5 && dd >= 14 && dd <= 20) return { id: 'holidayparty', name: 'Holiday party', start: 17 * 60, emoji: '🎄' };
  if ((m === 12 && dd >= 24 && dd <= 26) || (m === 1 && dd === 1)) return { id: 'closed', name: m === 1 ? "New Year's Day" : 'Winter holidays', closed: true, emoji: m === 1 ? '🎆' : '❄️' };
  if (m === 2 && dd === 14) return { id: 'valentines', name: "Valentine's Day", start: 11 * 60, emoji: '💌' };
  if (m === 3 && dd === 3) return { id: 'picabday', name: "Pica's birthday", start: 15 * 60, emoji: '🐶' };
  return null;
}
function decorOf(day) { if (CAL.epoch == null) return null; const d = calDate(day), m = d.getMonth() + 1, dd = d.getDate(); return m === 10 && dd >= 20 ? 'halloween' : m === 12 ? 'winter' : m === 2 && dd >= 10 && dd <= 14 ? 'valentine' : null; }

function creditName(id) { return PERSONA[id]?.short ?? FORMER[id]?.split(' ')[0].replace(/"/g, '') ?? id; }

class Studio {
  constructor(data) {
    this.projects = data?.projects ?? [];
    this.nextProjectId = data?.nextProjectId ?? 1;
    this.clientIdx = data?.clientIdx ?? 0;
    this.awardsWon = data?.awardsWon ?? [];
    this.submissions = data?.submissions ?? [];
    this.news = data?.news ?? [];
    this.firedRituals = data?.firedRituals ?? {};
    this.artifacts = data?.artifacts ?? [];
    this.nextArtifactId = data?.nextArtifactId ?? 1;
  }

  toJSON() { return { ...this }; }

  addNews(t, text, icon = '📣') {
    this.news.push({ t, text, icon });
    if (this.news.length > 60) this.news.shift();
  }

  createProject(t, spec, team, dueDays = 18, { pitch = false } = {}) {
    const p = {
      id: `p${this.nextProjectId++}`,
      name: spec.name, client: spec.client, type: spec.type, brief: spec.brief,
      internal: spec.client.startsWith('Another Studio'), contact: spec.contact ?? null,
      phase: 0, progress: 0, quality: 55, team, lead: team[0],
      log: [], createdAt: t, dueDay: Math.floor(t / 1440) + dueDays,
      submittedTo: null, awaitingReview: false, reviews: [], revisionRound: 0,
      workstreams: [...WORKSTREAMS[spec.type]],
    };
    const h = hashStr(spec.name);
    p.dna = { palette: h % PALETTES.length, font: (h >>> 4) % FONTS.length, motif: (h >>> 8) % MOTIFS.length, seed: h };
    p.tasks = [];
    if (pitch) {
      // Pitch first: a short competitive phase against Studio Ditto. Win it to get the real work.
      p.pitching = true; p.pitchDue = t + 3 * 1440;
      const mk = (title, skill, kind, subs) => ({ id: `${p.id}t${p.tasks.length + 1}`, phase: 0, workstream: 'Pitch', title, skill, kind, owner: [...team].sort((a, b) => this.skillOf(b, skill) - this.skillOf(a, skill))[0], status: 'todo', artifacts: [], subtasks: subs.map(x => ({ title: x, done: false })), dependsOn: null });
      p.tasks.push(mk('Pitch strategy', 'research', 'research', ['Read the brief twice', 'Find the insight', 'One-sentence idea']));
      p.tasks.push(mk('Pitch creative', 'design', 'moodboard', ['Territories', 'Key visual', 'Pick the bravest']));
      p.tasks.push(mk('Pitch deck', 'writing', 'deckcover', ['Story arc', 'Slides', 'Rehearse']));
    } else for (const ws of p.workstreams) this.#addWorkstream(p, ws, 0);
    this.projects.push(p);
    return p;
  }

  pitchResult(t, p, won) {
    p.pitching = false; p.awaitingReview = false; p.visitRequested = null;
    if (won) { p.progress = 0; p.phase = 0; for (const ws of p.workstreams) this.#addWorkstream(p, ws, 0); p.dueDay = Math.floor(t / 1440) + 18; }
    else { p.lost = true; p.phase = 4; p.archived = true; p.deliveredAt = t; }
  }

  #addWorkstream(p, ws, fromPhase) {
    const load = {};
    for (const tk of p.tasks) load[tk.owner] = (load[tk.owner] ?? 0) + 1;
    let prev = null;
    WS[ws].forEach((phaseTasks, pi) => {
      const ids = [];
      for (const tpl of phaseTasks) {
        if (pi < fromPhase) continue;
        const owner = [...p.team].sort((a, b) => (this.skillOf(b, tpl.skill) - (load[b] ?? 0) * 0.06) - (this.skillOf(a, tpl.skill) - (load[a] ?? 0) * 0.06))[0];
        load[owner] = (load[owner] ?? 0) + 1;
        const id = `${p.id}t${p.tasks.length + 1}`;
        p.tasks.push({ id, phase: pi, workstream: ws, title: tpl.title, skill: tpl.skill, kind: tpl.kind, owner, status: 'todo', artifacts: [], subtasks: tpl.subs.map(s => ({ title: s, done: false })), dependsOn: prev });
        ids.push(id);
      }
      if (ids.length) prev = ids[ids.length - 1];
    });
  }

  skillOf(id, skill) { return PERSONA[id]?.skills?.[skill] ?? 0.5; }

  // The task a person works on next: their own open task in the current
  // phase, else the open task in the phase that best fits their skills.
  taskFor(agentId, p) {
    const open = p.tasks.filter(t => t.phase === p.phase && t.status !== 'done');
    return open.find(t => t.owner === agentId)
      ?? open.sort((a, b) => (this.skillOf(agentId, b.skill) - b.artifacts.length * 0.08) - (this.skillOf(agentId, a.skill) - a.artifacts.length * 0.08))[0]
      ?? p.tasks.filter(t => t.phase === p.phase).pop();
  }

  #syncTasks(p) {
    for (const t of p.tasks) if (t.phase < p.phase) { t.status = 'done'; t.subtasks.forEach(s => s.done = true); }
    const cur = p.tasks.filter(t => t.phase === p.phase);
    const doneN = Math.floor((Math.min(100, p.progress) / 100) * cur.length);
    [...cur].sort((a, b) => b.artifacts.length - a.artifacts.length).forEach((t, i) => {
      if (i < doneN) { t.status = 'done'; t.subtasks.forEach(s => s.done = true); }
      else if (t.artifacts.length) { t.status = 'doing'; t.subtasks.forEach((s, j) => s.done = j < Math.min(t.artifacts.length, t.subtasks.length - 1)); }
    });
  }

  addArtifact(t, p, task, agentId, note, extra = {}) {
    const versions = task.artifacts.length + 1;
    const a = {
      id: `a${this.nextArtifactId++}`, project: p.id, task: task.id, agent: agentId, t,
      kind: task.kind, phase: Math.min(p.phase, 3), workstream: task.workstream,
      title: `${task.title}${versions > 1 ? ` v${versions}` : ''}`,
      note, quality: Math.round(p.quality), seed: (p.dna.seed ^ (this.nextArtifactId * 2654435761)) >>> 0, ...extra,
    };
    this.artifacts.push(a);
    task.artifacts.push(a.id);
    if (task.status !== 'done') task.status = 'doing';
    const live = this.artifacts.filter(x => !x.archive);
    if (live.length > 450) {
      const old = live[0];
      this.artifacts.splice(this.artifacts.indexOf(old), 1);
      for (const pr of this.projects) for (const tk of pr.tasks ?? []) tk.artifacts = tk.artifacts.filter(x => x !== old.id);
    }
    return a;
  }

  // Seeded projects start mid-flight: give their finished tasks artifacts.
  backfill(p, t) {
    for (const task of p.tasks.filter(x => x.phase < p.phase || (x.phase === p.phase && p.progress > 30 && Math.random() < 0.5))) {
      const phaseBefore = p.phase; p.phase = task.phase;
      const at = t - ((phaseBefore - task.phase) * 3 + 1) * 1440 + (hashStr(task.id) % 480);
      this.addArtifact(at, p, task, task.owner, `${task.title}: ${task.subtasks.map(s => s.title.toLowerCase()).join(', ')}.`);
      p.phase = phaseBefore;
    }
    this.#syncTasks(p);
  }

  // The studio's first 99 days: delivered projects, their artifacts, and awards.
  // Bump when the pre–Day 100 archive changes; older saves get the new archive on load.
  refreshArchive() {
    if (this.archiveVersion === ARCHIVE_VERSION) return null;
    const old = new Set(this.projects.filter(p => p.archived).map(p => p.id));
    const names = this.projects.filter(p => p.archived).map(p => p.name), clients = this.projects.filter(p => p.archived).map(p => p.client);
    this.projects = this.projects.filter(p => !old.has(p.id));
    this.artifacts = this.artifacts.filter(a => !old.has(a.project));
    this.awardsWon = this.awardsWon.filter(w => !w.archive);
    this.seedArchive();
    // old name → new name, for memories that mention the old archive
    return Object.fromEntries([...names.map((n, i) => [n, ARCHIVE[i]?.name]), ...clients.map((c, i) => [c, ARCHIVE[i]?.client])].filter(([a, b]) => b && a !== b));
  }
  seedArchive() {
    this.archiveVersion = ARCHIVE_VERSION;
    for (const spec of ARCHIVE) {
      const end = (spec.day - 1) * 1440 + 17 * 60;
      const p = this.createProject(end - 16 * 1440, spec, spec.team);
      if (spec.domain) p.domain = spec.domain;
      if (spec.font != null) p.dna.font = spec.font; // product UI wants an interface face, not a display serif
      if (spec.motif != null) p.dna.motif = spec.motif;
      if (spec.story) p.story = spec.story;
      p.caseStudy = !!spec.cs;
      p.archived = true; p.preLayoff = spec.day < LAYOFF_DAY; p.phase = 4; p.progress = 0;
      p.deliveredAt = end; p.quality = 80 + (hashStr(spec.name) % 13);
      for (const task of p.tasks) {
        if ((hashStr(task.id) % 100) < 40) continue;
        const at = end - (4 - task.phase) * 4 * 1440 + (hashStr(task.title) % 600);
        this.addArtifact(at, { ...p, phase: task.phase }, task, task.owner, `${task.title} for ${spec.client}.`, { archive: true, phase: task.phase });
      }
      for (const task of p.tasks) { task.status = 'done'; task.subtasks.forEach(s => s.done = true); }
      p.reviews = [0, 1, 2, 3].map(ph => ({ phase: ph, outcome: 'approved', round: 1 + (hashStr(spec.name + ph) % 2) }));
      if (spec.award) this.awardsWon.push({ award: spec.award.name, project: spec.name, t: (spec.award.day - 1) * 1440 + 15 * 60, archive: true });
      this.archiveCaseStudy(p);
      this.archiveEntry(p);
    }
  }

  // The award book for each award a pre–Day 100 project won (also backfills older saves).
  archiveEntry(p) {
    if (!p.archived) return;
    for (const w of this.awardsWon.filter(w => w.archive && w.project === p.name)) {
      const id = `${p.id}en${w.award.replace(/\W+/g, '_')}`;
      if (p.tasks.some(t => t.id === id)) continue;
      const task = { id, phase: 3, workstream: 'Award entry', title: `Entry: ${w.award}`, skill: 'writing', kind: 'entry', owner: p.lead, status: 'done', artifacts: [], subtasks: [{ title: 'Write the entry', done: true }], dependsOn: null };
      p.tasks.push(task);
      this.addArtifact(w.t - 2 * 1440, { ...p, phase: 3 }, task, p.lead, `${w.award} entry for ${p.name}. ${p.brief}`, { archive: true, phase: 3, award: w.award, won: true });
    }
  }
  // The whiteboard always has a few Venn diagrams on it: if a world has fewer than three,
  // the studio sketches some for active projects (also gives older saves something to see).
  sketchVenns(t) {
    const have = this.artifacts.filter(a => a.kind === 'venn').length;
    for (const p of this.active().filter(p => !p.internal).slice(0, Math.max(0, 3 - have))) {
      const task = { id: `${p.id}vn${this.nextArtifactId}`, phase: p.phase, workstream: 'Strategy', title: 'Whiteboard: where it overlaps', skill: 'research', kind: 'venn', owner: p.lead, status: 'done', artifacts: [], subtasks: [], dependsOn: null };
      p.tasks.push(task);
      this.addArtifact(t - 60, p, task, p.lead, `A whiteboard session for ${p.name}: three things we have to get right, and where they meet.`, { phase: Math.min(p.phase, 3) });
    }
  }
  // Research boards every world should have a couple of: personas, a positioning matrix,
  // a segmentation and a business model canvas. Each lands on randomly picked projects.
  sketchResearch(t) {
    const pool = this.projects.filter(p => !p.internal || p.archived);
    for (const [kind, title, ws] of [['personas', 'User personas', 'Research'], ['matrix', 'Positioning matrix', 'Strategy'], ['segments', 'Audience segmentation', 'Research'], ['canvas', 'Business model canvas', 'Strategy']]) {
      const have = this.artifacts.filter(a => a.kind === kind).length;
      const picks = [...pool].sort(() => Math.random() - 0.5).slice(0, Math.max(0, 2 - have));
      for (const p of picks) {
        const task = { id: `${p.id}rs${this.nextArtifactId}`, phase: 0, workstream: ws, title, skill: 'research', kind, owner: p.lead, status: 'done', artifacts: [], subtasks: [], dependsOn: null };
        p.tasks.push(task);
        const at = p.archived ? (p.createdAt ?? t) + 1440 : t - 120;
        this.addArtifact(at, { ...p, phase: 0 }, task, p.lead, `${title} for ${p.name}.`, { phase: 0, ...(p.archived ? { archive: true } : {}) });
      }
    }
  }
  // The case study for a project delivered before Day 100 (also backfills older saves).
  archiveCaseStudy(p) {
    if (!p.archived || !p.caseStudy || p.tasks.some(t => t.kind === 'casestudy')) return;
    const task = { id: `${p.id}cs`, phase: 3, workstream: 'Case study', title: 'Case study', skill: 'writing', kind: 'casestudy', owner: p.lead, status: 'done', artifacts: [], subtasks: [{ title: 'Write the story', done: true }, { title: 'Pick the hero images', done: true }], dependsOn: null };
    p.tasks.push(task);
    const arts = this.artifacts.filter(x => x.project === p.id);
    const rounds = (p.reviews ?? []).reduce((n, r) => n + (r.round ?? 1), 0), kinds = new Set(arts.map(x => x.kind)).size;
    const award = this.awardsWon.find(w => w.project === p.name);
    const note = `${p.brief} We worked across ${p.workstreams.join(', ')}, through ${rounds} client review${rounds === 1 ? '' : 's'}. ${kinds} kinds of work, delivered at quality ${Math.round(p.quality)}.${award ? ` Won at ${award.award}.` : ''}`;
    this.addArtifact((p.deliveredAt ?? p.createdAt) - 120, { ...p, phase: 3 }, task, p.lead, note, { archive: true, phase: 3 });
  }

  nextBrief() {
    const taken = new Set(this.projects.map(p => p.name));
    for (let i = 0; i < CLIENT_POOL.length; i++) {
      const spec = CLIENT_POOL[(this.clientIdx + i) % CLIENT_POOL.length];
      if (!taken.has(spec.name)) { this.clientIdx += i + 1; return spec; }
    }
    return null;
  }

  // Two weeks after a project finishes, keep its record (tasks, work, credits) but drop
  // the working detail nobody looks at again, so long-running saves stay small.
  compactFinished(now) {
    for (const p of this.projects) {
      if (p.phase < 4 || p.compacted || now - (p.deliveredAt ?? now) < 14 * 1440) continue;
      p.tasks = p.tasks.map(({ id, phase, workstream, title, skill, kind, owner, status, artifacts }) => ({ id, phase, workstream, title, skill, kind, owner, status, artifacts, subtasks: [], dependsOn: null }));
      p.log = [];
      p.compacted = true;
    }
  }
  active() { return this.projects.filter(p => p.phase < 4 && !p.lost); }
  get(id) { return this.projects.find(p => p.id === id); }
  forAgent(id) { return this.active().filter(p => p.team.includes(id)); }

  // A work session moves a project forward. Points scale with time, the
  // person's relevant skill, and how fulfilled they feel. A phase can only
  // close when the client (or Adaeze, for internal work) approves it.
  work(t, agentId, persona, projectId, minutes, fulfillment, contribution) {
    const p = this.get(projectId);
    if (!p || p.phase >= 4) return null;
    const s = persona.skills;
    const skill = Math.max(s.design, s.research * 0.9, s.writing * 0.9, s.product * 0.8, s.client * 0.6);
    const lanes = Math.max(2, p.workstreams.length);
    const pts = (minutes / 60) * 3.2 * (0.4 + skill) * (0.6 + fulfillment / 250) * (3 / lanes);
    p.progress = Math.min(100, p.progress + pts);
    p.quality = Math.min(97, p.quality + (skill * 92 - p.quality) * 0.025 + (contribution ? 0.2 : 0) + (p.awaitingReview ? 0.15 : 0));
    let artifact = null;
    if (contribution) {
      p.log.push({ t, agent: agentId, text: contribution });
      if (p.log.length > 60) p.log.shift();
      const task = this.taskFor(agentId, p);
      if (task) artifact = this.addArtifact(t, p, task, agentId, contribution);
      if (artifact) p.log[p.log.length - 1].artifact = artifact.id;
    }
    let advanced = null, readyForReview = false, readyToPitch = false;
    if (p.pitching) { if (p.progress >= 100 && !p.awaitingReview) { p.awaitingReview = true; readyToPitch = true; } }
    else if (p.progress >= 100 && !p.awaitingReview) {
      if (p.internal) advanced = this.advance(p);
      else { p.awaitingReview = true; readyForReview = true; }
    }
    this.#syncTasks(p);
    return { project: p, advanced, artifact, readyForReview, readyToPitch };
  }

  advance(p) {
    p.reviews.push({ phase: p.phase, outcome: 'approved', round: p.revisionRound + 1 });
    p.progress = 0; p.phase++; p.awaitingReview = false; p.revisionRound = 0;
    this.#syncTasks(p);
    return PHASES[p.phase];
  }

  // Client review outcome. Returns a summary the sim turns into news + memories.
  clientDecision(t, p, decision, feedback) {
    const phaseName = PHASES[p.phase];
    if (decision === 'approve') {
      p.quality = Math.min(100, p.quality + 3);
      const advanced = this.advance(p);
      return { advanced, text: `${p.contact?.name ?? p.client} approved the ${phaseName} work on "${p.name}".` };
    }
    p.awaitingReview = false;
    p.revisionRound++;
    p.reviews.push({ phase: p.phase, outcome: decision, round: p.revisionRound, feedback });
    const lead = p.lead;
    const addTask = (title, kind, subs) => p.tasks.push({ id: `${p.id}t${p.tasks.length + 1}`, phase: p.phase, workstream: 'Client feedback', title, skill: 'design', kind, owner: lead, status: 'todo', artifacts: [], subtasks: subs.map(s => ({ title: s, done: false })), dependsOn: null });
    const lastKind = p.tasks.filter(x => x.phase === p.phase && x.workstream !== 'Client feedback').pop()?.kind ?? 'poster';
    if (decision === 'changes') {
      p.progress = 68;
      p.quality = Math.min(100, p.quality + 1.5);
      addTask(`Revision round ${p.revisionRound}`, lastKind, [feedback, 'Revise and re-present', 'Internal review']);
      return { text: `${p.contact?.name ?? p.client} asked for changes on "${p.name}": ${feedback}` };
    }
    if (decision === 'scope') {
      const add = SCOPE_ADDS.find(w => !p.workstreams.includes(w));
      p.progress = Math.max(0, p.progress - 25);
      p.dueDay += 6;
      if (add) { p.workstreams.push(add); this.#addWorkstream(p, add, p.phase); }
      return { text: `${p.contact?.name ?? p.client} expanded the scope of "${p.name}"${add ? ` to include ${add}` : ''}. Deadline moved to Day ${p.dueDay + 1}.` };
    }
    // reject: back to the drawing board for this phase
    p.progress = 25;
    p.quality = Math.max(30, p.quality - 3);
    addTask('Rethink the direction', lastKind, [feedback, 'New territories', 'Re-present']);
    return { text: `${p.contact?.name ?? p.client} rejected the ${phaseName} direction on "${p.name}". Back to the drawing board.` };
  }

  nextAwardFor(t) {
    const day = Math.floor(t / 1440);
    return AWARDS.find(a => a.deadlineDay >= day && !this.submissions.some(s => s.award === a.id && s.count >= 3));
  }

  submit(t, project, award) {
    project.submittedTo = award.id;
    let s = this.submissions.find(x => x.award === award.id);
    if (!s) { s = { award: award.id, projects: [], count: 0, decided: false }; this.submissions.push(s); }
    s.projects.push(project.id);
    s.count++;
  }

  summary(forAgent = null) {
    const lines = this.active().map(p => {
      const mine = forAgent && p.team.includes(forAgent) ? ' [YOU ARE ON THIS]' : '';
      return `- ${p.id} "${p.name}" for ${p.client} (${p.type}; ${p.workstreams.join(', ')}): phase ${PHASES[p.phase]} ${Math.round(p.progress)}%${p.awaitingReview ? ' (awaiting client review)' : ''}, quality ${Math.round(p.quality)}, due Day ${p.dueDay + 1}, team ${p.team.join(', ')}${mine}. Brief: ${p.brief}`;
    });
    const delivered = this.projects.filter(p => p.phase >= 4 && !p.archived).slice(-4).map(p => p.name);
    const news = this.news.slice(-5).map(n => `- ${n.text}`);
    return [
      'Active projects:', ...lines,
      delivered.length ? `Recently delivered: ${delivered.join(', ')}` : '',
      this.awardsWon.length ? `Awards won: ${this.awardsWon.map(a => `${a.award} for ${a.project}`).join('; ')}` : 'Awards won: none yet this season.',
      'Studio news:', ...(news.length ? news : ['- (quiet so far)']),
    ].filter(Boolean).join('\n');
  }
}

