    const body = ctx.createLinearGradient(x, 0, x + jw, 0); body.addColorStop(0, darken(col, 0.25)); body.addColorStop(0.18, lighten(col, 0.12)); body.addColorStop(0.5, col); body.addColorStop(1, darken(col, 0.45));
    box(ctx, x, y + 32, jw, jh - 32, body, 22);
    // label: pattern band + typographic hierarchy
    const lx = x + 10, ly = y + 74, lw = jw - 20, lh = 150;
    box(ctx, lx, ly, lw, lh, lighten(P0, 0.35), 3);
    ctx.save(); ctx.beginPath(); ctx.rect(lx, ly, lw, 30); ctx.clip(); box(ctx, lx, ly, lw, 30, col);
    for (let k = 0; k < 7; k++) motif(ctx, d.motif, lx + 10 + k * 22, ly + 15, 7, alpha(P0, 0.8), P3); ctx.restore();
    text(ctx, d.name.toUpperCase(), lx + lw / 2, ly + 50, fit(ctx, d.name.toUpperCase(), 11, d.text, lw - 16, '700', 2), d.text, P4, { align: 'center', weight: '700', track: 2 });
    text(ctx, fl, lx + lw / 2, ly + 92, fit(ctx, fl, 32, d.font, lw - 14), d.font, col, { align: 'center', italic: d.fontKind.includes('serif') });
    line(ctx, lx + 20, ly + 106, lx + lw - 20, ly + 106, alpha(P4, 0.25));
    text(ctx, 'Pepper sauce · small batch', lx + lw / 2, ly + 122, 8.5, d.text, ART.muted, { align: 'center' });
    text(ctx, 'NET WT 340 g', lx + lw / 2, ly + 138, 8, d.text, ART.muted, { align: 'center', track: 1 });
