  if (kind === 4) { ctx.moveTo(-s * 0.3, s * 0.3); ctx.lineTo(-s * 0.3, s * 0.1); ctx.lineTo(-s * 0.1, s * 0.1); ctx.lineTo(-s * 0.1, -s * 0.1); ctx.lineTo(s * 0.1, -s * 0.1); ctx.lineTo(s * 0.1, -s * 0.3); ctx.lineTo(s * 0.3, -s * 0.3); ctx.stroke(); }
  if (kind === 5) { ctx.arc(-s * 0.15, -s * 0.22, s * 0.08, 0, 7); ctx.arc(s * 0.15, -s * 0.22, s * 0.08, 0, 7); ctx.fill(); ctx.fillRect(-s * 0.24, -s * 0.08, s * 0.18, s * 0.38); ctx.beginPath(); ctx.moveTo(s * 0.15, -s * 0.1); ctx.lineTo(s * 0.28, s * 0.18); ctx.lineTo(s * 0.02, s * 0.18); ctx.closePath(); ctx.fill(); }
  ctx.restore();
