      icon(ctx, 'pin', x + 24, sy + 64, 12, ART.muted); text(ctx, d.name, x + 36, sy + 68, 11, d.text, ART.muted);
      icon(ctx, 'clock', x + 120, sy + 64, 12, ART.muted); text(ctx, '35 min', x + 132, sy + 68, 11, d.text, ART.muted);
      [['12.4', 'km'], ['48', 'min'], ['320', 'kcal']].forEach(([v, u], i) => { const tx = x + 18 + i * (w - 36) / 3; box(ctx, tx, sy + 82, (w - 36) / 3 - 8, 52, alpha(P2, 0.25), 10); text(ctx, v, tx + 10, sy + 108, 17, d.font, ink, { weight: '600' }); text(ctx, u, tx + 10, sy + 124, 9.5, d.text, ART.muted); });
      areaChart(ctx, x + 18, sy + 148, w - 36, 60, P1, R);
      box(ctx, x + 18, y + h - 70, w - 36, 46, P1, 23); text(ctx, copy.cta, x + w / 2, y + h - 42, 13, d.text, P0 === surf ? ART.white : P0, { align: 'center', weight: '600' });
