      ctx.save(); ctx.beginPath(); ctx.arc(x + w / 2, y + 96, 36, 0, Math.PI * 2); ctx.clip(); photo(ctx, x + w / 2 - 36, y + 60, 72, 72, 'portrait', d, 24); ctx.restore();
      text(ctx, PEOPLE[d.a.seed % PEOPLE.length][0], x + w / 2, y + 152, 17, d.font, ink, { align: 'center', weight: '600' });
