    box(ctx, px + 14, py + ph * 0.6, pw - 28, 34, P3, 17); text(ctx, copy.cta, px + pw / 2, py + ph * 0.6 + 21, 11, d.text, ink, { align: 'center', weight: '600' });
    ctx.save(); rr(ctx, px + 14, py + ph * 0.72, pw - 28, 72, 8); ctx.clip(); photo(ctx, px + 14, py + ph * 0.72, pw - 28, 72, 'stilllife', d, 44); ctx.restore();
