    for (let k = 0; k < 4; k++) box(ctx, px + 10 + k * (pw - 20) / 4, py + 34, (pw - 20) / 4 - 4, 3, alpha(ART.white, k ? 0.45 : 0.95), 2);
    const gg = ctx.createLinearGradient(0, py + ph * 0.5, 0, py + ph); gg.addColorStop(0, alpha(P4, 0)); gg.addColorStop(1, alpha(P4, 0.8)); box(ctx, px, py, pw, ph, gg);
    wrap(ctx, d.tag, pw - 32, 24, d.font, '600').slice(0, 2).forEach((l, i) => text(ctx, l, px + 16, py + ph - 96 + i * 28, 24, d.font, ART.white, { weight: '600' }));
    box(ctx, px + 16, py + ph - 46, pw - 32, 32, alpha(ART.white, 0.9), 16); text(ctx, 'See more', px + pw / 2, py + ph - 26, 11, d.text, ART.ink, { align: 'center', weight: '600' });
