  box(ctx, bx + bw * 0.28, by + bh, 12, c.h - bh - 74, darken(P4, 0.2)); box(ctx, bx + bw * 0.7, by + bh, 12, c.h - bh - 74, darken(P4, 0.2));
  shadow(ctx, true, 30, 14); box(ctx, bx - 10, by - 10, bw + 20, bh + 20, darken(P4, 0.3)); shadow(ctx, false);
  ctx.save(); ctx.beginPath(); ctx.rect(bx, by, bw, bh); ctx.clip();
  photo(ctx, bx + bw * 0.45, by, bw * 0.55, bh, photoFor(d, 7), d, 61);
