  wrap(ctx, d.tag, bw * 0.42, 36, d.font, '600').slice(0, 2).forEach((l, i) => text(ctx, l, bx + 26, by + 62 + i * 40, 36, d.font, P0, { weight: '600' }));
  motif(ctx, d.motif, bx + 38, by + bh - 34, 14, P0, P3); text(ctx, d.name, bx + 60, by + bh - 28, 14, d.font, P0, { weight: '600' });
  grain(ctx, bx, by, bw, bh, 0.08);
