  const loc = act.loc ?? '', desc = act.desc ?? '';
  if (P[a.id]?.look?.dog) return /nap|sleep|curl|snooz|bed/i.test(desc) || loc === 'dog_bed' ? 'dognap' : null;
  if (/nap/i.test(desc)) return 'doze';
