  const m = snap.t % 1440;
  const busy = snap.agents.some(a => !a.hidden && Math.abs(a.x - COFFEE.spot.x) + Math.abs(a.y - COFFEE.spot.y) <= 1);
  if (!busy && !(m > 7 * 60 + 30 && m < 10 * 60)) return;
